const root=document.querySelector('#root');const maps=window.MAP_DATA||[];const aliases={Ascent:'亚海悬城',Bind:'源工重镇',Haven:'隐世修所',Split:'霓虹町',Icebox:'森寒冬港',Breeze:'微风岛屿',Fracture:'裂变峡谷',Pearl:'深海明珠',Lotus:'莲华古城',Sunset:'日落之城',Abyss:'幽邃地窟',Corrode:'盐海矿镇'};
let current=maps[0],query='',mapObserver,admin=false,username='',editing=false,overrides={},revision=0,drafts={},draftRevisions={},selected=null,dragging=false,online=false,saving=false,page='home';
const name=m=>aliases[m.en?.displayName]||m.displayName;
const calibrated=m=>Number.isFinite(m.xMultiplier)&&Number.isFinite(m.yMultiplier)&&m.xMultiplier!==0&&m.yMultiplier!==0;
const dirty=()=>Object.values(drafts).some(d=>Object.keys(d).length);
function notice(text,error=false){const el=document.querySelector('#notice');el.textContent=text;el.className=error?'error':'success'}
async function api(url,method='GET',data){const r=await fetch('/api/'+url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(10000)});const result=await r.json();if(!r.ok){const e=Error(result.error||'操作失败');e.status=r.status;throw e}return result}
function header(){document.querySelector('#identity').textContent=admin?'管理员 · '+username:'游客 · 免登录';document.querySelector('#admin').textContent=admin?'管理员后台':'管理员登录'}
function home(){document.title='森希Valorant · 首页';page='home';mapObserver?.disconnect();root.innerHTML='<div class="brand-hero"><img src="brand/senxi-mark.svg" alt="森希品牌标志"><div><h2>森希Valorant</h2><p>看懂地图，练好道具，打出配合。</p></div></div><h1>每一处点位，<br>都是战术的起点。</h1><p>默认以游客身份浏览，随时查看管理员保存的最新地图标注。</p><button class="entry" id="enter"><small>01 / EXPLORE</small><b>地图 ↗</b><span>探索各个地图 · 查询点位名称 · 俯视图定位</span></button><button class="entry utility-entry" id="enter-lineups"><small>战术资料</small><b>道具点位 ↗</b><span>选择地图与英雄 · 学习道具用法 · 管理员维护</span></button><button class="entry entry-crosshair" id="enter-crosshairs"><small>瞄准工具</small><b>准星设置 ↗</b><span>准星库 · 生成器 · 设置教程</span></button><div class="soon">＋ 更多工具，将在这里陆续加入</div>';document.querySelector('#enter-crosshairs').onclick=()=>showCrosshairs();document.querySelector('#enter').onclick=show;document.querySelector('#enter-lineups').onclick=()=>showLineups()}
function show(){document.title='地图资料库 · 森希Valorant';page='maps';root.innerHTML='<div class="brand-section"><img src="brand/senxi-mark.svg" alt=""><span>森希Valorant / 地图资料库</span></div><h1>地图资料库<span style="color:#ff4655">.</span></h1><p>圆点表示位置，名称通过引线连接圆点。管理员保存的校准位置会同步给所有游客。</p><div class="toolbar"><input aria-label="搜索地图或点位" placeholder="搜索地图 / 点位名称…" id="search"><button id="reload">同步最新资料 ↻</button><button id="edit" hidden>编辑点位</button><button id="save" hidden>保存本地图</button><button id="cancel" hidden>撤销本地图修改</button></div><p id="status"></p><div id="edit-help"></div><div class="layout"><nav id="maps"></nav><section class="panel" id="detail"></section></div>';document.querySelector('#search').value=query;document.querySelector('#search').oninput=e=>{query=e.target.value.trim().toLowerCase();render()};document.querySelector('#reload').onclick=()=>sync(true);document.querySelector('#edit').onclick=()=>{editing=!editing;render()};document.querySelector('#save').onclick=save;document.querySelector('#cancel').onclick=()=>{delete drafts[current.uuid];render();notice('已撤销本地图未保存修改')};render()}
async function sync(manual=false){try{const data=await api('positions');online=true;if(data.revision!==revision||manual){overrides=data.overrides;revision=data.revision;if(!dragging&&page==='maps')render()}if(manual)notice(dirty()?'已同步最新已保存位置，当前草稿保留':'已同步最新位置');connection()}catch(e){online=false;connection();if(manual)notice('无法连接服务，请通过“启动地图工具.cmd”打开项目',true)}}
function connection(){document.querySelector('#connection').textContent=online?'服务已连接 · 游客每3秒同步':'离线预览 · 管理和同步需要启动服务'}
async function save(){const mapId=current.uuid,positions=drafts[mapId];if(!positions||!Object.keys(positions).length)return notice('本地图没有待保存的修改');saving=true;renderControls();try{const data=await api('positions','PUT',{mapId,positions,revision:draftRevisions[mapId]??revision});overrides=data.overrides;revision=data.revision;delete drafts[mapId];notice('已保存，游客将在3秒内同步');render()}catch(e){if(e.status===401){admin=false;editing=false;header()}notice(e.message,true)}finally{saving=false;renderControls()}}
function renderControls(){const edit=document.querySelector('#edit');if(!edit)return;edit.hidden=!admin;edit.disabled=!online||saving;edit.textContent=editing?'结束编辑':'编辑点位';for(const id of ['save','cancel']){const b=document.querySelector('#'+id);b.hidden=!admin||!editing;b.disabled=saving||!Object.keys(drafts[current.uuid]||{}).length}document.querySelector('#save').textContent=saving?'保存中…':'保存本地图';document.querySelector('#edit-help').textContent=admin&&editing?'拖拽名称或圆点调整位置。未定位点位可先点击下方名称，再点击地图放置。修改后点击“保存本地图”。':'游客仅可浏览；管理员保存后位置会自动同步。'}
function position(m,c,i){return drafts[m.uuid]?.[i]||overrides[m.uuid]?.[i]||(calibrated(m)?{x:c.location.y*m.xMultiplier+m.xScalarToAdd,y:c.location.x*m.yMultiplier+m.yScalarToAdd}:null)}
function stage(i,p){if(!drafts[current.uuid]||!Object.keys(drafts[current.uuid]).length)draftRevisions[current.uuid]=revision;(drafts[current.uuid]??={})[i]=p;const status=document.querySelector('#status');if(status)status.textContent=maps.filter(m=>[name(m),m.en?.displayName,...m.callouts.map(c=>c.superRegionName+' '+c.regionName)].join(' ').toLowerCase().includes(query)).length+' 张地图 · 有未保存修改';renderControls()}
function pointerPosition(e,canvas){const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function attachDrag(pin,canvas,i,start){pin.onpointerdown=e=>{if(!admin||!editing||saving||e.button!==0)return;e.preventDefault();e.stopPropagation();const original=position(current,current.callouts[i],i),at=pointerPosition(e,canvas);let moved=false;dragging=true;pin.setPointerCapture(e.pointerId);pin.onpointermove=ev=>{const q=pointerPosition(ev,canvas),dx=q.x-at.x,dy=q.y-at.y;if(!moved&&Math.abs(dx)+Math.abs(dy)<.003)return;moved=true;const p={x:Math.max(0,Math.min(1,original.x+dx)),y:Math.max(0,Math.min(1,original.y+dy))};pin.style.left=p.x*100+'%';pin.style.top=p.y*100+'%';stage(i,p);layoutLabels(canvas)};const finish=()=>{dragging=false;pin.onpointermove=null;pin.onpointerup=null;pin.onpointercancel=null;if(moved){pin.dataset.dragged='yes';notice('位置已调整，尚未保存');layoutLabels(canvas)}};pin.onpointerup=finish;pin.onpointercancel=finish}}
function render(){mapObserver?.disconnect();if(page!=='maps')return;const match=m=>[name(m),m.en?.displayName,...m.callouts.map(c=>c.superRegionName+' '+c.regionName)].join(' ').toLowerCase().includes(query),list=maps.filter(match);if(!list.includes(current))current=list[0];const nav=document.querySelector('#maps');nav.replaceChildren();for(const m of list){const b=document.createElement('button');b.textContent=name(m);b.className=m===current?'active':'';b.onclick=()=>{current=m;selected=null;render()};nav.append(b)}const d=document.querySelector('#detail');d.replaceChildren();document.querySelector('#status').textContent=list.length+' 张地图 · '+(dirty()?'有未保存修改':'已保存版本 '+revision);if(!current){d.textContent='未找到匹配的地图或点位';return}renderControls();const m=current,h=document.createElement('h2');h.textContent=name(m);d.append(h);const p=document.createElement('p');p.textContent=m.en?.displayName+' / '+m.callouts.length+' 个点位 · '+Object.keys(overrides[m.uuid]||{}).length+' 个已校准';d.append(p);if(!calibrated(m)||['Breeze','Summit','Corrode'].includes(m.en?.displayName)){const warning=document.createElement('p');warning.className='warning';warning.textContent=calibrated(m)?'部分原始坐标与底图不一致，可由管理员拖拽校准。':'原始资料缺少转换参数。管理员可选中点位名称后，点击地图进行定位。未校准点位仅列出名称。';d.append(warning)}const zoom=document.createElement('input');zoom.type='range';zoom.min='100';zoom.max='250';zoom.value='100';zoom.setAttribute('aria-label','地图缩放');const zl=document.createElement('label');zl.textContent='地图缩放 ';zl.append(zoom);d.append(zl);const viewport=document.createElement('div');viewport.className='map-viewport';const canvas=document.createElement('div');canvas.className='map'+(admin&&editing?' editable':'');const image=document.createElement('img');image.src=m.displayIcon;image.alt=name(m)+'俯视图';image.draggable=false;canvas.append(image);viewport.append(canvas);d.append(viewport);const tags=document.createElement('div');tags.className='tags';m.callouts.forEach((c,i)=>{const label=[c.superRegionName,c.regionName].filter(Boolean).join(' · '),b=document.createElement('button'),pos=position(m,c,i);b.textContent=label+(!pos?'（待定位）':'');b.dataset.point=i;const pin=document.createElement('button');pin.className='pin';pin.dataset.point=i;pin.setAttribute('aria-label',label);const text=document.createElement('span');text.className='pin-label';text.textContent=label;pin.append(text);if(pos){pin.style.left=pos.x*100+'%';pin.style.top=pos.y*100+'%';canvas.append(pin);attachDrag(pin,canvas,i,pos)}if(overrides[m.uuid]?.[i]||drafts[m.uuid]?.[i])pin.classList.add('calibrated');const select=()=>{selected=i;tags.querySelectorAll('button').forEach(x=>x.classList.remove('active'));canvas.querySelectorAll('.pin').forEach(x=>x.classList.remove('selected'));b.classList.add('active');pin.classList.add('selected');if(!pos&&admin&&editing)notice('已选择“'+label+'”，请点击地图放置')};b.onclick=()=>{select();if(pos)pin.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'})};pin.onclick=e=>{e.stopPropagation();if(pin.dataset.dragged){delete pin.dataset.dragged;return}select()};if(selected===i){b.classList.add('active');pin.classList.add('selected')}tags.append(b)});d.append(tags);canvas.onclick=e=>{if(!admin||!editing||saving||selected===null||e.target.closest('.pin'))return;stage(selected,pointerPosition(e,canvas));notice('点位已放置，尚未保存');render()};zoom.oninput=()=>{canvas.style.width=zoom.value+'%';requestAnimationFrame(()=>layoutLabels(canvas))};const place=()=>layoutLabels(canvas);image.onload=place;mapObserver=new ResizeObserver(place);mapObserver.observe(canvas);requestAnimationFrame(place)}
function openPanel(){const dialog=document.querySelector('#account-dialog');document.querySelector('#dialog-body').innerHTML=admin?'<h2>管理员后台</h2><p>地图校准</p><button id="open-editor">进入地图编辑</button><button id="open-lineups">管理道具点位</button><button id="open-crosshairs">管理准星</button><hr><h3>账号设置</h3><form id="account-form"><label>新账号<input name="username" autocomplete="username" maxlength="64" required></label><label>当前密码<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input name="password" type="password" autocomplete="new-password" maxlength="256" required></label><label>确认新密码<input name="confirm" type="password" autocomplete="new-password" required></label><button type="submit">保存账号与密码</button></form><p>保存后所有管理员会话退出，请使用新账号重新登录。</p><hr><button id="logout">退出管理员，返回游客</button><p class="muted">更多管理功能将在这里扩展。</p>':'<h2>管理员登录</h2><p>游客无需登录即可浏览。管理员登录后可校准地图。</p><form id="login-form"><label>账号<input name="username" autocomplete="username" required></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">登录管理员</button></form>';document.querySelector('#dialog-error').textContent='';if(admin){document.querySelector('#open-crosshairs').onclick=()=>{dialog.close();showCrosshairs('library')};document.querySelector('#open-lineups').onclick=()=>{dialog.close();showLineups()};document.querySelector('#account-form').elements.username.value=username;document.querySelector('#open-editor').onclick=()=>{dialog.close();editing=true;show()};document.querySelector('#logout').onclick=async()=>{if((dirty()||window.lineupUnsaved?.()||window.crosshairUnsaved?.())&&!confirm('有未保存的修改，退出将丢弃草稿。是否继续？'))return;try{await api('logout','POST',{});admin=false;username='';editing=false;drafts={};header();dialog.close();if(page==='maps')render();if(page==='lineups')showLineups();if(page==='crosshairs')showCrosshairs();notice('已切换为游客')}catch(e){document.querySelector('#dialog-error').textContent=e.message}};document.querySelector('#account-form').onsubmit=async e=>{e.preventDefault();const f=e.target.elements;if(f.password.value!==f.confirm.value)return document.querySelector('#dialog-error').textContent='两次新密码不一致';if((dirty()||window.lineupUnsaved?.()||window.crosshairUnsaved?.()))return document.querySelector('#dialog-error').textContent='请先保存或撤销地图草稿，再修改账号';const submit=e.target.querySelector('button');submit.disabled=true;try{await api('account','PUT',{username:f.username.value,currentPassword:f.currentPassword.value,password:f.password.value});admin=false;editing=false;username='';header();if(page==='maps')render();if(page==='lineups')showLineups();if(page==='crosshairs')showCrosshairs();openPanel();notice('账号已更新，请重新登录')}catch(err){document.querySelector('#dialog-error').textContent=err.message}finally{submit.disabled=false}}}else document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target.elements,button=e.target.querySelector('button');button.disabled=true;try{const data=await api('login','POST',{username:f.username.value,password:f.password.value});admin=data.admin;username=data.username;header();dialog.close();openPanel();notice('管理员登录成功')}catch(err){document.querySelector('#dialog-error').textContent=err.message}finally{button.disabled=false}};const brand=document.createElement('div');brand.className='dialog-brand';brand.innerHTML='<img src="brand/senxi-mark.svg" alt=""><span>森希Valorant · 管理中心</span>';document.querySelector('#dialog-body').prepend(brand);if(!dialog.open)dialog.showModal()}
document.querySelector('#brand-home').onclick=e=>{e.preventDefault();home()};document.querySelector('#home').onclick=home;document.querySelector('#admin').onclick=openPanel;document.querySelector('#close-dialog').onclick=()=>document.querySelector('#account-dialog').close();window.addEventListener('beforeunload',e=>{if((dirty()||window.lineupUnsaved?.()||window.crosshairUnsaved?.())){e.preventDefault();e.returnValue=''}});header();home();sync();api('session').then(s=>{admin=s.admin;username=s.username||'';header()}).catch(()=>{});setInterval(()=>{if(!dragging&&!saving)sync()},3000);

function layoutLabels(canvas){if(!canvas.isConnected)return;const W=canvas.clientWidth,H=canvas.clientHeight;if(!W||!H)return;canvas.querySelector('.leaders')?.remove();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('leaders');svg.setAttribute('viewBox','0 0 '+W+' '+H);canvas.insertBefore(svg,canvas.querySelector('.pin'));const used=[];canvas.querySelectorAll('.pin').forEach(pin=>{const label=pin.querySelector('.pin-label'),w=label.offsetWidth,h=label.offsetHeight,x=parseFloat(pin.style.left)*W/100,y=parseFloat(pin.style.top)*H/100;let best=null;for(const dy of [-14,-40,28,-66,54,-92])for(const dx of [0,-40,40,-80,80]){const cx=Math.max(w/2+3,Math.min(W-w/2-3,x+dx)),bottom=Math.max(h+3,Math.min(H-3,y+dy)),box={l:cx-w/2,r:cx+w/2,t:bottom-h,b:bottom};let overlap=used.reduce((n,b)=>n+Math.max(0,Math.min(b.r,box.r)-Math.max(b.l,box.l)+4)*Math.max(0,Math.min(b.b,box.b)-Math.max(b.t,box.t)+4),0);const score=overlap*1000+Math.abs(cx-x)+Math.abs(bottom-y+14);if(!best||score<best.score)best={...box,cx,bottom,score}}used.push(best);label.style.left=(4+best.cx-x)+'px';label.style.top=(4+best.bottom-y)+'px';const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('x1',x);line.setAttribute('y1',y);line.setAttribute('x2',best.cx);line.setAttribute('y2',best.bottom>y?best.t:best.bottom);svg.append(line)})}
